using UnityEngine;
using UnityEngine.UI;
using UnityEditor;

public class SetupCookingSceneExisting
{
    public static string Main()
    {
        var sb = new System.Text.StringBuilder();

        // === 1. Find objek Masak ===
        var masak = GameObject.Find("Masak");
        if (masak == null)
        {
            var allGOs = Object.FindObjectsByType<Transform>(FindObjectsSortMode.None);
            foreach (var t in allGOs)
            {
                if (t.name == "Masak") { masak = t.gameObject; break; }
            }
        }
        if (masak == null) return "ERROR: Objek Masak tidak ditemukan di scene!";
        sb.AppendLine("[OK] Masak ditemukan: " + masak.name);

        // === 2. Tambah BoxCollider jika belum ada ===
        var col = masak.GetComponent<BoxCollider>();
        if (col == null)
        {
            col = masak.AddComponent<BoxCollider>();
            col.isTrigger = true;
            col.size = new Vector3(3f, 3f, 3f);
            col.center = new Vector3(0f, 1f, 0f);
            sb.AppendLine("[OK] BoxCollider ditambahkan");
        }
        else
        {
            col.isTrigger = true;
            sb.AppendLine("[OK] BoxCollider sudah ada");
        }

        // === 3. Find PanelMemasak & PromptMasak ===
        GameObject panelMemasakGO = null;
        GameObject promptMasakGO = null;

        var allCanvas = Object.FindObjectsByType<Canvas>(FindObjectsSortMode.None);
        foreach (var c in allCanvas)
        {
            var panel = c.transform.Find("PanelMemasak");
            if (panel != null) panelMemasakGO = panel.gameObject;

            var prompt = c.transform.Find("PromptMasak");
            if (prompt != null) promptMasakGO = prompt.gameObject;
        }

        if (panelMemasakGO == null) return "ERROR: PanelMemasak tidak ditemukan di Canvas!";
        if (promptMasakGO == null) return "ERROR: PromptMasak tidak ditemukan di Canvas!";

        sb.AppendLine("[OK] PanelMemasak dan PromptMasak ditemukan");
        panelMemasakGO.SetActive(false);
        promptMasakGO.SetActive(false);

        // === 4. Setup CookingTrigger di Masak ===
        var trigger = masak.GetComponent<CookingTrigger>();
        if (trigger == null)
        {
            trigger = masak.AddComponent<CookingTrigger>();
            sb.AppendLine("[OK] CookingTrigger ditambahkan");
        }

        trigger.cookingCanvas = panelMemasakGO;
        trigger.promptUI = promptMasakGO;
        sb.AppendLine("[OK] CookingTrigger di-wire ke PanelMemasak & PromptMasak");

        // === 5. Setup CookingUI di PanelMemasak ===
        var cookingUI = panelMemasakGO.GetComponent<CookingUI>();
        if (cookingUI == null)
        {
            cookingUI = panelMemasakGO.AddComponent<CookingUI>();
            sb.AppendLine("[OK] CookingUI ditambahkan ke PanelMemasak");
        }

        // Load recipes
        string recipeFolder = "Assets/Herbal/Recipes";
        string[] recipeNames = { "Jamu Jahe", "Jamu Kunyit", "Jamu Kencur", "Jamu Temulawak", "Wedang Jahe", "Jamu Beras Kencur" };
        var recipes = new System.Collections.Generic.List<CookingRecipe>();

        foreach (var rn in recipeNames)
        {
            var recipe = AssetDatabase.LoadAssetAtPath<CookingRecipe>(recipeFolder + "/" + rn + ".asset");
            if (recipe != null) recipes.Add(recipe);
        }
        cookingUI.recipes = recipes.ToArray();
        sb.AppendLine($"[OK] {recipes.Count} resep di-assign");

        // Wire References di PanelMemasak
        var leftPanel = panelMemasakGO.transform.Find("LeftPanel");
        var rightPanel = panelMemasakGO.transform.Find("RightPanel");
        var btnClose = panelMemasakGO.transform.Find("BtnClose");

        if (leftPanel != null) cookingUI.leftPanel = leftPanel.GetComponent<RectTransform>();
        if (btnClose != null) cookingUI.closeButton = btnClose.GetComponent<Button>();
        cookingUI.cookingTrigger = trigger;

        if (rightPanel != null)
        {
            var tRecipeName = rightPanel.Find("TxtRecipeName");
            var tRecipeDesc = rightPanel.Find("TxtRecipeDesc");
            var imgFood = rightPanel.Find("ImgFood");
            var tHpRestore = rightPanel.Find("TxtHPRestore");
            var btnMasak = rightPanel.Find("BtnMasak");

            if (tRecipeName != null) cookingUI.recipeName = tRecipeName.GetComponent<Text>();
            if (tRecipeDesc != null) cookingUI.recipeDescription = tRecipeDesc.GetComponent<Text>();
            if (imgFood != null) cookingUI.recipeImage = imgFood.GetComponent<Image>();
            if (tHpRestore != null) cookingUI.hpRestoreText = tHpRestore.GetComponent<Text>();
            if (btnMasak != null) cookingUI.cookButton = btnMasak.GetComponent<Button>();

            var slots = new System.Collections.Generic.List<GameObject>();
            var icons = new System.Collections.Generic.List<Image>();
            var names = new System.Collections.Generic.List<Text>();
            var amounts = new System.Collections.Generic.List<Text>();

            for (int i = 0; i < 4; i++)
            {
                var slot = rightPanel.Find("IngredientSlot_" + i);
                if (slot != null)
                {
                    slots.Add(slot.gameObject);
                    var icon = slot.Find("Icon");
                    var nameT = slot.Find("Name");
                    var amountT = slot.Find("Amount");

                    if (icon != null) icons.Add(icon.GetComponent<Image>()); else icons.Add(null);
                    if (nameT != null) names.Add(nameT.GetComponent<Text>()); else names.Add(null);
                    if (amountT != null) amounts.Add(amountT.GetComponent<Text>()); else amounts.Add(null);
                }
            }

            cookingUI.ingredientSlots = slots.ToArray();
            cookingUI.ingredientIcons = icons.ToArray();
            cookingUI.ingredientNames = names.ToArray();
            cookingUI.ingredientAmounts = amounts.ToArray();

            // Coba temukan pesan status (TxtBottomBar) jika ada
            var txtBottomBar = panelMemasakGO.transform.Find("TxtBottomBar");
            if (txtBottomBar != null) cookingUI.statusMessage = txtBottomBar.GetComponent<Text>();

            sb.AppendLine("[OK] Semua komponen UI di-wire dengan benar");
        }

        // Save Scene
        UnityEditor.SceneManagement.EditorSceneManager.MarkSceneDirty(
            UnityEngine.SceneManagement.SceneManager.GetActiveScene()
        );
        sb.AppendLine("[OK] Scene marked dirty");

        return sb.ToString();
    }
}
